<script setup lang="ts">
import { UiButton, UiTextarea } from '@/ui/base'
import { computed, onMounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { useRoute, useRouter } from 'vue-router'
import { useEnterpriseStore } from '@/stores/enterprise'
import { useUiStore } from '@/stores/ui'
import type { Member, MemberAction, MemberStatus } from '@/types/enterprise'
import { downloadCsv } from '@/utils/format'
import PageHeading from '@/ui/common/PageHeading.vue'
import AppIcon from '@/ui/common/AppIcon.vue'
import AppPagination from '@/ui/common/AppPagination.vue'
import EmptyState from '@/ui/common/EmptyState.vue'
import UiDialog from '@/ui/common/UiDialog.vue'
import MemberOverview from '@/features/enterprise/components/members/MemberOverview.vue'
import MemberFilters,{type MemberFilterValue} from '@/features/enterprise/components/members/MemberFilters.vue'
import MemberTable,{type MemberSortKey} from '@/features/enterprise/components/members/MemberTable.vue'
import MemberActionDialog from '@/features/enterprise/components/members/MemberActionDialog.vue'
import MemberDetailDrawer from '@/features/enterprise/components/members/MemberDetailDrawer.vue'
import MemberBulkDialog from '@/features/enterprise/components/members/MemberBulkDialog.vue'
import type { EnterpriseDomain } from '@/services/enterprise/dataSource'
import { currentAuthorizationAllows } from '@/services/runtime/authorization'
const store=useEnterpriseStore(),ui=useUiStore(),route=useRoute(),router=useRouter(),{t,locale}=useI18n()
const defaultFilters=():MemberFilterValue=>({query:'',role:'',department:'',status:''}); const filters=ref(defaultFilters()),page=ref(1),pageSize=ref(10),selected=ref<string[]>([]),action=ref<MemberAction>('create'),actionOpen=ref(false),target=ref<Member|null>(null),detailId=ref<string|null>(null),more=ref<Member|null>(null),sortKey=ref<MemberSortKey>(),sortDirection=ref<'asc'|'desc'>('asc'),batchOpen=ref(false),batchAction=ref<'activate'|'suspend'>('suspend'),batchTargets=ref<{id:string;version:number}[]>([]),mounted=ref(false)
const detail=computed(()=>store.members.find(m=>m.id===detailId.value)??null)
const recycleOpen=ref(false),restoreTarget=ref<Member|null>(null),restoreReason=ref(''),restoreBusy=ref(false)
const apiAllows=(code:string)=>store.previewMode||currentAuthorizationAllows(code)
const apiAllowsAll=(codes:string[])=>store.previewMode||codes.every(currentAuthorizationAllows)
const canCreateMember=computed(()=>store.previewMode)
const canInviteMember=computed(()=>apiAllowsAll(['tenant.member.invite','tenant.member.profile.update','tenant.role.assign_member']))
const canEditMember=computed(()=>apiAllows('tenant.member.profile.update'))
const canChangeRoles=computed(()=>apiAllowsAll(['tenant.role.assign_member','tenant.role.revoke_member']))
const canReadBusinessScope=computed(()=>apiAllows('tenant.member.business_scope.get'))
const canEditBusinessScope=computed(()=>apiAllowsAll(['tenant.member.business_scope.get','tenant.member.business_scope.set','tenant.member.scope_candidates']))
const canActivateMember=computed(()=>apiAllows('tenant.member.activate'))
const canSuspendMember=computed(()=>apiAllows('tenant.member.suspend'))
const canRemoveMember=computed(()=>apiAllows('tenant.member.remove'))
const canListRemovedMembers=computed(()=>apiAllows('tenant.member.list_removed'))
const canRestoreMember=computed(()=>apiAllowsAll(['tenant.member.restore','tenant.role.assign_member']))
const canResetPassword=computed(()=>store.previewMode)
const canExportMembers=computed(()=>store.previewMode)
const canMoreMemberActions=computed(()=>canEditMember.value||canChangeRoles.value||canActivateMember.value||canSuspendMember.value||canRemoveMember.value||canResetPassword.value)
const filtered=computed(()=>{if(!store.previewMode)return store.members;const {query,role,department,status}=filters.value;const result=store.members.filter(m=>(!query||`${m.name} ${m.email} ${m.phone} ${m.employeeId}`.toLowerCase().includes(query.trim().toLowerCase()))&&(!role||m.roleIds.includes(role))&&(!department||m.departmentId===department)&&(!status||m.status===status));if(!sortKey.value)return result;const key=sortKey.value;return[...result].sort((a,b)=>{const value=(m:Member)=>key==='departmentId'?store.departmentName(m.departmentId):String(m[key]??'');return value(a).localeCompare(value(b),locale.value,{numeric:true})*(sortDirection.value==='asc'?1:-1)})})
const total=computed(()=>store.previewMode?filtered.value.length:store.memberTotal)
const paged=computed(()=>store.previewMode?filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value):store.members),selection=computed(()=>store.members.filter(m=>selected.value.includes(m.id))),canActivate=computed(()=>canActivateMember.value&&selection.value.length>0&&selection.value.every(m=>m.status==='suspended')),canSuspend=computed(()=>canSuspendMember.value&&selection.value.length>0&&selection.value.every(m=>m.status==='active'))
watch([page,pageSize],()=>{selected.value=[];if(mounted.value&&!store.previewMode)void loadMembers()});watch(()=>total.value,()=>{const next=Math.min(page.value,Math.max(1,Math.ceil(total.value/pageSize.value)));if(next!==page.value)page.value=next});watch(()=>ui.module,module=>{if(module)detailId.value=null});watch(()=>store.tenantId,()=>{if(mounted.value&&!store.previewMode){page.value=1;selected.value=[];detailId.value=null;void loadMembers()}});watch(()=>route.query,q=>{if(typeof q.q==='string'||typeof q.department==='string')applyFilters({...defaultFilters(),query:typeof q.q==='string'?q.q:'',department:typeof q.department==='string'?q.department:''});if(q.action==='create'||q.action==='invite'){if(q.action==='create'?canCreateMember.value:canInviteMember.value)openAction(q.action);void router.replace({path:route.path,query:{}})}},{immediate:true})
function scopeLabel(scope:Member['scope']){return t(`members.scopes.${scope==='department_tree'?'department':scope==='self'?'own':scope}`)}
function statusLabel(status:Member['status']){return t(`members.statuses.${status}`)}
function loadMembers(){return store.queryMembers({query:filters.value.query,roleId:filters.value.role,departmentId:filters.value.department,status:filters.value.status as MemberStatus|'',page:page.value,pageSize:pageSize.value})}
function applyFilters(value:MemberFilterValue){filters.value={...value};page.value=1;selected.value=[];detailId.value=null;if(mounted.value&&!store.previewMode)void loadMembers()}
function clear(){applyFilters(defaultFilters())}
function sort(key:MemberSortKey){if(!store.previewMode)return;sortDirection.value=sortKey.value===key&&sortDirection.value==='asc'?'desc':'asc';sortKey.value=key;page.value=1;selected.value=[]}
function memberActionAllowed(kind:MemberAction){if(store.previewMode)return true;return kind==='create'?canCreateMember.value:kind==='invite'?canInviteMember.value:kind==='edit'?canEditMember.value:kind==='role'?canChangeRoles.value:kind==='reset'?false:kind==='activate'?canActivateMember.value:kind==='suspend'?canSuspendMember.value:kind==='remove'?canRemoveMember.value:false}
function openAction(kind:MemberAction,member:Member|null=null){if(!memberActionAllowed(kind))return;action.value=kind;target.value=member?(JSON.parse(JSON.stringify(member)) as Member):null;more.value=null;detailId.value=null;actionOpen.value=true}
function showMore(member:Member){detailId.value=null;more.value=member}
function openBatch(kind:'activate'|'suspend'){batchAction.value=kind;batchTargets.value=selection.value.map(m=>({id:m.id,version:m.version}));batchOpen.value=true}
function finishBatch(){batchOpen.value=false;selected.value=[]}
async function openRecycle(){if(!canListRemovedMembers.value)return;recycleOpen.value=true;restoreTarget.value=null;restoreReason.value='';try{await store.queryRemovedMembers()}catch(error){ui.toast(error instanceof Error?error.message:t('members.recycle.loadFailed'),'error')}}
function closeRecycle(){if(restoreBusy.value)return;recycleOpen.value=false;restoreTarget.value=null;restoreReason.value=''}
function chooseRestore(member:Member){restoreTarget.value=member;restoreReason.value=''}
async function confirmRestore(){if(!restoreTarget.value||!restoreReason.value.trim())return;restoreBusy.value=true;try{await store.restoreMember(restoreTarget.value.id,restoreTarget.value.version,restoreReason.value);ui.toast(t('members.recycle.success'),'success');restoreTarget.value=null;restoreReason.value=''}catch(error){ui.toast(error instanceof Error?error.message:t('members.recycle.failed'),'error')}finally{restoreBusy.value=false}}
function exportMembers(){try{const output=selected.value.length?filtered.value.filter(m=>selected.value.includes(m.id)):filtered.value;downloadCsv(t('members.exportFile'),[[t('members.columns.name'),t('members.columns.contact'),t('members.department'),t('members.role'),t('members.columns.scope'),t('members.columns.status'),t('members.columns.lastLogin'),t('members.columns.joinedAt')],...output.map(m=>[m.name,`${m.phone} / ${m.email}`,store.departmentName(m.departmentId),m.roleIds.map(store.roleName).join(', '),scopeLabel(m.scope),statusLabel(m.status),m.lastLogin||'',m.joinedAt])]);store.audit(t('members.auditModule'),t('members.auditExport'),t('members.auditCount',{count:output.length}));ui.toast(t('members.exportSuccess',{count:output.length}))}catch(e){ui.toast((e as Error).message,'error')}}
function readableMemberDomains(){
  const domains:EnterpriseDomain[]=store.previewMode?['members']:[]
  if(apiAllows('tenant.role.list'))domains.push('roles')
  if(apiAllows('tenant.department.list'))domains.push('departments')
  return domains
}
onMounted(async()=>{try{await store.ensureDomains(readableMemberDomains());mounted.value=true;if(!store.previewMode)await loadMembers()}catch{mounted.value=true}})
</script>
<template>
  <div class="members-view" data-enterprise-page="members" data-ui-template="ListPage" :class="{'has-detail':Boolean(detail)}"><div class="member-main"><div class="page-stack members-stack"><PageHeading :title="t('members.title')" :description="t('members.description')" banner compact/><MemberOverview/><MemberFilters data-ui-region="query" :value="filters" @apply="applyFilters" @reset="clear"/><section data-ui-region="data" class="card member-data-panel" :aria-label="t('members.listAria')"><div class="row-between member-toolbar" data-ui-region="toolbar"><div class="row wrap member-tools"><UiButton v-if="canCreateMember" class="btn btn-primary" @click="openAction('create')"><AppIcon name="plus" :size="16"/>{{ t('members.add') }}</UiButton><UiButton v-if="canInviteMember" class="btn invite-button" @click="openAction('invite')"><AppIcon name="invite" :size="16"/>{{ t('members.invite') }}</UiButton><UiButton v-if="canActivateMember" class="btn" :disabled="!canActivate" @click="openBatch('activate')"><AppIcon name="checks" :size="15"/>{{ t('members.batchActivate') }}</UiButton><UiButton v-if="canSuspendMember" class="btn" :disabled="!canSuspend" @click="openBatch('suspend')"><AppIcon name="lock" :size="14"/>{{ t('members.batchSuspend') }}</UiButton><UiButton v-if="canListRemovedMembers" class="btn" @click="openRecycle">{{ t('members.recycleBin') }}</UiButton><UiButton v-if="canExportMembers" class="btn" :aria-label="selected.length?t('members.exportSelected'):t('members.exportList')" @click="exportMembers"><AppIcon name="download" :size="15"/>{{ t('common.export') }}</UiButton></div><span class="selection-label">{{ t('common.selected',{count:selected.length}) }}<span v-if="selected.length"> · {{ t('common.currentPage') }}</span></span></div><MemberTable v-if="paged.length" v-model:selected="selected" :members="paged" :detail-id="detailId" :can-edit="canEditMember" :can-more="canMoreMemberActions" :sortable="store.previewMode" :sort-key="sortKey" :sort-direction="sortDirection" @sort="sort" @detail="detailId=$event.id" @edit="openAction('edit',$event)" @more="showMore"/><EmptyState v-else><UiButton class="btn" @click="clear">{{ t('members.clearFilters') }}</UiButton></EmptyState><AppPagination data-ui-region="pagination" v-model:page="page" v-model:page-size="pageSize" :total="total"/></section></div></div><MemberActionDialog :open="actionOpen" :action="action" :member="target" @close="actionOpen=false"/><MemberDetailDrawer :member="detail" :can-edit="canEditMember" :can-change-roles="canChangeRoles" :can-read-scope="canReadBusinessScope" :can-edit-scope="canEditBusinessScope" :can-more="canMoreMemberActions" @close="detailId=null" @action="openAction" @more="showMore"/><MemberBulkDialog :open="batchOpen" :action="batchAction" :targets="batchTargets" @close="batchOpen=false" @saved="finishBatch"/><UiDialog :open="recycleOpen" :title="t('members.recycle.title')" width="640px" @close="closeRecycle"><div class="recycle-stack"><p class="recycle-hint">{{ t('members.recycle.description') }}</p><div v-if="store.removedMembers.length" class="recycle-list"><article v-for="member in store.removedMembers" :key="member.id" class="recycle-row"><div><strong>{{ member.name }}</strong><span>{{ member.email || member.phone || member.username }}</span></div><UiButton v-if="canRestoreMember" class="btn" @click="chooseRestore(member)">{{ t('members.recycle.restore') }}</UiButton></article></div><EmptyState v-else>{{ t('members.recycle.empty') }}</EmptyState></div></UiDialog><UiDialog :open="Boolean(restoreTarget)" :title="t('members.recycle.restoreTitle',{name:restoreTarget?.name??''})" width="520px" @close="()=>{if(!restoreBusy){restoreTarget=null;restoreReason=''}}"><div class="restore-stack"><p>{{ t('members.recycle.restoreDescription') }}</p><label><span>{{ t('members.recycle.reason') }}</span><UiTextarea v-model="restoreReason" class="restore-reason" maxlength="500" :placeholder="t('members.recycle.reasonPlaceholder')"/></label></div><template #footer><UiButton class="btn" :disabled="restoreBusy" @click="()=>{restoreTarget=null;restoreReason=''}">{{ t('common.cancel') }}</UiButton><UiButton class="btn btn-primary" :disabled="restoreBusy||!restoreReason.trim()" @click="confirmRestore">{{ restoreBusy?t('common.processing'):t('members.recycle.confirm') }}</UiButton></template></UiDialog><UiDialog :open="Boolean(more)" :title="t('members.operations',{name:more?.name??''})" width="420px" @close="more=null"><div v-if="more" class="member-operation-list"><UiButton @click="()=>{detailId=more!.id;more=null}"><AppIcon name="eye"/>{{ t('members.viewFull') }}</UiButton><UiButton v-if="canEditMember" @click="openAction('edit',more)"><AppIcon name="edit"/>{{ t('members.editInfo') }}</UiButton><UiButton v-if="canChangeRoles" @click="openAction('role',more)"><AppIcon name="shield"/>{{ t('members.roleChange') }}</UiButton><UiButton v-if="canResetPassword" @click="openAction('reset',more)"><AppIcon name="key"/>{{ t('members.resetPassword') }}</UiButton><UiButton v-if="canSuspendMember&&more.status==='active'" class="text-danger" @click="openAction('suspend',more)"><AppIcon name="lock"/>{{ t('members.disableAccess') }}</UiButton><UiButton v-if="canActivateMember&&more.status==='suspended'" @click="openAction('activate',more)"><AppIcon name="success"/>{{ t('members.reactivate') }}</UiButton><UiButton v-if="canRemoveMember&&more.status!=='removed'" class="text-danger" @click="openAction('remove',more)"><AppIcon name="logout"/>{{ t('members.removeAndHandover') }}</UiButton></div></UiDialog></div>
</template>
<style scoped>
.member-main{min-width:0;max-width:100%;container-type:inline-size;container-name:member-main}.members-view{min-width:0;max-width:100%;overflow-x:clip}.members-stack{gap:16px}.member-data-panel{padding:0 12px 12px;border-radius:var(--radius-md)}.member-toolbar{min-height:68px;padding:14px 0;flex-wrap:wrap;gap:10px}.member-tools{gap:8px}.member-tools .btn{border-color:var(--color-border)}.member-tools .btn-primary{border-color:var(--color-primary)}.member-tools .invite-button{color:var(--color-primary)}.selection-label{color:var(--color-text-muted);font-size:11px;white-space:normal;margin-left:auto}.member-data-panel :deep(.pagination){padding:20px 2px 5px;font-size:12px}.member-data-panel :deep(.pagination-controls){gap:5px}.member-operation-list{display:flex;flex-direction:column;gap:5px}.member-operation-list button{display:flex;align-items:center;gap:12px;padding:13px;border-radius:7px;text-align:left}.member-operation-list button:hover{background:var(--color-surface-soft)}.member-operation-list .icon{color:var(--color-text-secondary)}.member-operation-list .text-danger .icon{color:var(--color-danger)}@media(min-width:1280px){.members-view{transition:margin-right .24s cubic-bezier(.2,.8,.2,1)}.members-view.has-detail{margin-right:var(--member-detail-width)}}@container member-main (max-width:790px){.member-tools{gap:6px}.member-tools .btn{padding:0 10px;font-size:12px}.member-data-panel :deep(.page-jump){display:none}}@media(prefers-reduced-motion:reduce){.members-view{transition:none}}
.recycle-stack,.restore-stack{display:flex;flex-direction:column;gap:14px}.recycle-hint,.restore-stack>p{color:var(--color-text-secondary);font-size:12px;line-height:1.65}.recycle-list{display:flex;flex-direction:column;gap:8px}.recycle-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px;border:1px solid var(--color-border);border-radius:var(--radius-sm)}.recycle-row strong,.recycle-row span{display:block}.recycle-row span{margin-top:4px;color:var(--color-text-muted);font-size:11px}.restore-stack label>span{display:block;margin-bottom:7px;font-size:12px;font-weight:600}.restore-reason{width:100%;min-height:110px;padding:10px;resize:vertical}@media(max-width:640px){.recycle-row{align-items:stretch;flex-direction:column}}</style>
